const projectId = $('Receive Project').first().json.project_id;
const project = $('Load Project').first().json;
const design = $('Load Selected Design Option').first().json;
const briefing = $('Load Briefing').first().json;
const agentPrompt = $('Load Agent Prompt').first().json;

const designContent = design || {};
const briefingContent = briefing || {};

const designStr = JSON.stringify(designContent).toLowerCase();
const briefStr = JSON.stringify(briefingContent).toLowerCase();
const hasStructural = designStr.includes('estructur') || briefStr.includes('estructur') || designStr.includes('structural');

const roomsAffected = briefingContent.rooms_affected || [];
const constraints = briefingContent.constraints || [];

const designSummary = design.title
  ? `Opción ${design.option_number}: ${design.title}\n${design.description || ''}`
  : JSON.stringify(designContent, null, 2);

const roomsText = roomsAffected.length > 0
  ? roomsAffected.map(r => `- ${r.room}: ${r.intervention}`).join('\n')
  : '- Sin detalle disponible';

const constraintsText = constraints.length > 0
  ? constraints.map(c => `- ${c.description}`).join('\n')
  : '- Sin restricciones específicas';

const CCAA_MAP = {
  'A Coruña': 'Galicia', 'Lugo': 'Galicia', 'Ourense': 'Galicia', 'Pontevedra': 'Galicia',
  'Álava': 'País Vasco', 'Vizcaya': 'País Vasco', 'Guipúzcoa': 'País Vasco',
  'Navarra': 'Navarra', 'La Rioja': 'La Rioja',
  'Huesca': 'Aragón', 'Teruel': 'Aragón', 'Zaragoza': 'Aragón',
  'Barcelona': 'Cataluña', 'Girona': 'Cataluña', 'Lleida': 'Cataluña', 'Tarragona': 'Cataluña',
  'Valencia': 'Comunitat Valenciana', 'Alicante': 'Comunitat Valenciana', 'Castellón': 'Comunitat Valenciana',
  'Murcia': 'Región de Murcia', 'Illes Balears': 'Illes Balears',
  'Las Palmas': 'Canarias', 'Santa Cruz de Tenerife': 'Canarias',
  'Cantabria': 'Cantabria', 'Asturias': 'Asturias',
  'Ávila': 'Castilla y León', 'Burgos': 'Castilla y León', 'León': 'Castilla y León',
  'Palencia': 'Castilla y León', 'Salamanca': 'Castilla y León', 'Segovia': 'Castilla y León',
  'Soria': 'Castilla y León', 'Valladolid': 'Castilla y León', 'Zamora': 'Castilla y León',
  'Albacete': 'Castilla-La Mancha', 'Ciudad Real': 'Castilla-La Mancha', 'Cuenca': 'Castilla-La Mancha',
  'Guadalajara': 'Castilla-La Mancha', 'Toledo': 'Castilla-La Mancha',
  'Badajoz': 'Extremadura', 'Cáceres': 'Extremadura',
  'Almería': 'Andalucía', 'Cádiz': 'Andalucía', 'Córdoba': 'Andalucía', 'Granada': 'Andalucía',
  'Huelva': 'Andalucía', 'Jaén': 'Andalucía', 'Málaga': 'Andalucía', 'Sevilla': 'Andalucía',
  'Madrid': 'Comunidad de Madrid', 'Ceuta': 'Ceuta', 'Melilla': 'Melilla'
};
const province = project.location_province || '';
const city = project.location_city || '';
const ccaa = CCAA_MAP[province] || province || 'no especificada';

const outputFormat = '{\n  "regulatory_tasks": [\n    {\n      "task_type": "licencia_obra|comunicacion_previa|permiso_comunidad|certificado_habitabilidad|cedula_urbanistica|informe_tecnico|otro",\n      "title": "string",\n      "description": "string",\n      "entity": "string",\n      "required_docs": ["string"],\n      "estimated_timeline": "string",\n      "estimated_cost": null,\n      "priority": "critico|importante|recomendable|informativo",\n      "normativa_confidence": "high|medium|low",\n      "citation_source": "Referencia legal específica: artículo, norma, plan urbanístico",\n      "draft_message": "string",\n      "notes": "string"\n    }\n  ]\n}';

const userPrompt = `Detecta trámites y permisos potencialmente necesarios para este proyecto.\n\nPROYECTO:\n- Tipo de intervención: ${project.project_type || 'reforma'}\n- Localización: ${city}, ${province}\n- Comunidad Autónoma: ${ccaa}\n- Tipo de inmueble: ${project.property_type || ''}\n- Superficie: ${project.property_area_m2 || ''} m²\n\nPROPUESTA DE DISTRIBUCIÓN SELECCIONADA:\n${designSummary}\n\nINTERVENCIONES PREVISTAS:\n${roomsText}\n\nRESTRICCIONES CONOCIDAS:\n${constraintsText}\n\n¿HAY AFECTACIÓN ESTRUCTURAL PREVISTA?: ${hasStructural ? 'Posiblemente sí' : 'No indicado explícitamente'}\n\nINSTRUCCIÓN CRÍTICA — NORMATIVA ESTRATIFICADA:\nAnaliza y distingue trámites según las tres capas normativas aplicables en España:\n\n1. CAPA NACIONAL (CTE, LOE, RD):\n   Aplica en toda España: CTE (DB-SI, DB-SUA, DB-HS, DB-HE, DB-SE), LOE, RITE.\n   En citation_source indica: CTE [Documento Básico] Art. [número] o RD [número]/[año].\n\n2. CAPA AUTONÓMICA (normativa de ${ccaa}):\n   Legislación propia de ${ccaa}: habitabilidad, accesibilidad, eficiencia energética, patrimonio.\n   En citation_source: Decreto/Ley [número] ${ccaa} Art. [número].\n   Si desconoces la normativa de ${ccaa}, usa normativa_confidence low y explícalo en notes.\n\n3. CAPA MUNICIPAL/LOCAL (Ayuntamiento de ${city}, PGOU):\n   Ordenanzas municipales, PGOU, licencias, comunicaciones previas.\n   En citation_source: PGOU ${city} Art. [número] u Ordenanza [nombre] Art. [número].\n   Si el PGOU de ${city} no está en tu base de conocimiento, usa normativa_confidence low e indica Verificar en Ayuntamiento.\n\nPara cada trámite especifica en qué capa normativa se basa y la referencia concreta.\n\nResponde EXCLUSIVAMENTE con un objeto JSON válido:\n${outputFormat}`;

// === STUDIO PROFILE INJECTION (B23) ===
const _studio = $('Load Studio Profile').first().json || {};
function _safeStudio(v){ if(v==null)return null; if(typeof v==='string'){try{return JSON.parse(v);}catch(e){return v;}} return v; }
const _id=_safeStudio(_studio.identity)||{},_priorities=_safeStudio(_studio.priorities)||[],_redLines=_safeStudio(_studio.red_lines)||[],_jur=_safeStudio(_studio.jurisdiction)||{};
const _SP_REG_LINES=[];
_SP_REG_LINES.push('Estudio: '+(_id.nombre_estudio||'estudio')+' en '+(_id.ciudad||'Espana')+'.');
_SP_REG_LINES.push('JURISDICCION DEL ESTUDIO: '+(_jur.ccaa||'Espana')+'. Ayuntamientos habituales: '+((_jur.ayuntamientos_habituales||[]).join(', ')||'-')+'.');
_SP_REG_LINES.push('PRIORIDADES (orden estricto):');
(_priorities||[]).forEach(p=>_SP_REG_LINES.push((p.orden||'?')+'. '+(p.prioridad||'')));
_SP_REG_LINES.push('LINEAS ROJAS:');
(_redLines||[]).forEach(l=>_SP_REG_LINES.push('- '+(l.texto||'')));
const _SP_REG=_SP_REG_LINES.join('\n');
// === END STUDIO PROFILE INJECTION ===
return [{ json: { agent_name: 'agent_regulatory',
  project_id: projectId,
  prompt_system: _SP_REG + '\n\n' + (agentPrompt.content || 'Eres el Agente de Normativa y Tramitación.'),
  prompt_user: userPrompt,
  model: (agentPrompt.model_recommended || 'claude-sonnet-4-20250514').trim(),
  temperature: agentPrompt.temperature || 0.2
}}];

const llmResponse = $input.first().json;
const projectId = $('Receive Project').first().json.project_id;

let content = llmResponse.text || llmResponse.content || llmResponse.response || '';
if (typeof content === 'object') content = JSON.stringify(content);
content = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(content);
} catch(e) {
  const match = content.match(/\{[\s\S]*\}/);
  if (match) { try { parsed = JSON.parse(match[0]); } catch(e2) {} }
}

const tasks = parsed.regulatory_tasks || [];

if (tasks.length === 0) {
  return [{ json: {
    project_id: projectId,
    task_type: 'otro',
    title: 'Análisis normativo preliminar',
    description: 'No se detectaron trámites específicos. Verificar manualmente con técnico.',
    entity: 'Ayuntamiento local',
    required_docs: '[]',
    estimated_timeline: 'Por determinar',
    estimated_cost: null,
    priority: 'informativo',
    normativa_confidence: 'low',
    citation_source: '',
    draft_message: '',
    notes: 'El LLM no devolvió trámites específicos.'
  }}];
}

return tasks.map(task => ({ json: {
  project_id: projectId,
  task_type: task.task_type || 'otro',
  title: task.title || 'Trámite sin título',
  description: task.description || '',
  entity: task.entity || '',
  required_docs: JSON.stringify(task.required_docs || []),
  estimated_timeline: task.estimated_timeline || '',
  estimated_cost: task.estimated_cost || null,
  priority: task.priority || 'informativo',
  normativa_confidence: task.normativa_confidence || 'low',
  citation_source: task.citation_source || '',
  draft_message: task.draft_message || '',
  notes: task.notes || ''
}}));

const approval = $('Create Approval').first().json;
const data = $('Collect All Tasks').first().json;
const resumeUrl = $execution.resumeUrl;

const approveUrl = resumeUrl + '?action=approve';
const rejectUrl = resumeUrl + '?action=reject';

const htmlBody = `<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;"><h2 style="color:#2c3e50;">Studio AI — Revisión normativa</h2><p>El análisis normativo ha detectado <strong>${data.critical_count} trámite(s) crítico(s)</strong> que pueden requerir consulta con organismos oficiales.</p><h3 style="color:#e67e22;">Trámites detectados:</h3><pre style="background:#f8f9fa;padding:16px;border-radius:4px;font-size:13px;white-space:pre-wrap;">${data.tasks_summary}</pre><p><strong>¿Autoriza preparar el contacto con los organismos correspondientes?</strong><br><em>Los borradores de comunicación están listos. El envío real requerirá su aprobación final.</em></p><div style="margin:30px 0;"><a href="${approveUrl}" style="background-color:#27ae60;color:white;padding:12px 24px;text-decoration:none;border-radius:4px;margin-right:16px;">✅ Autorizar contacto</a>&nbsp;&nbsp;<a href="${rejectUrl}" style="background-color:#95a5a6;color:white;padding:12px 24px;text-decoration:none;border-radius:4px;">⏸️ No por ahora</a></div><p style="color:#95a5a6;font-size:12px;">Este enlace expira en 72 horas.</p></div>`;

const archEmail = ($('Load Architect Email').first()?.json?.value) || 'botelladesdeel98@gmail.com';
return [{ json: {
  html_body: htmlBody,
  subject: `[Studio AI] Revisión normativa — ${data.critical_count} trámite(s) crítico(s)`,
  to: archEmail,
  project_id: data.project_id,
  tasks_count: data.tasks_count,
  critical_count: data.critical_count,
  approval_id: approval.id
}}];
